using System;
using System.Collections.Generic;
using System.Net;
using System.IO;
using System.Web.Script.Serialization;
public class NetworkExit {
 public string Ip,Country,CountryCode,Region,City,Isp;public DateTime CheckedUtc;
 public static NetworkExit Parse(string json){var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);object ok;if(!d.TryGetValue("success",out ok)||!(ok is bool)||!(bool)ok)throw new InvalidDataException("属地服务未返回有效结果");var r=new NetworkExit{Ip=Text(d,"ip"),Country=Text(d,"country"),CountryCode=Text(d,"country_code"),Region=Text(d,"region"),City=Text(d,"city"),CheckedUtc=DateTime.UtcNow};IPAddress ip;if(!IPAddress.TryParse(r.Ip,out ip)||String.IsNullOrWhiteSpace(r.Country))throw new InvalidDataException("出口数据不完整");object c;if(d.TryGetValue("connection",out c)&&c is Dictionary<string,object>)r.Isp=Text((Dictionary<string,object>)c,"isp");return r;}
 static string Text(Dictionary<string,object> d,string key){object v;return d.TryGetValue(key,out v)?Convert.ToString(v):"";}
 public string Status(MonitorConfig c){if(String.IsNullOrEmpty(c.ExpectedExitIp))return "尚未记录正常出口 · 请在 VPN 正常时确认";if(Ip==c.ExpectedExitIp)return "出口与已确认记录一致";return Country==c.ExpectedExitCountry?"出口 IP 已变化 · 属地仍一致，请核对节点":"出口属地已变化 · 请检查 VPN / 分流";}
 public static IWebProxy Proxy(string mode,string address){if(mode=="direct")return null;if(mode=="manual"){Uri uri;if(!Uri.TryCreate(address,UriKind.Absolute,out uri)||uri.Scheme!="http"||!String.IsNullOrEmpty(uri.UserInfo)||uri.AbsolutePath!="/"||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment))throw new ArgumentException("手动代理请输入 http://127.0.0.1:7890 格式，不包含账号密码或路径。");return new WebProxy(uri);}return WebRequest.GetSystemWebProxy();}
 public static string Failure(Exception e){var web=e as WebException;if(web!=null){var response=web.Response as HttpWebResponse;if(response!=null){int status=(int)response.StatusCode;response.Dispose();return "属地服务 HTTP "+status;}if(web.Status==WebExceptionStatus.Timeout)return "连接超时（8秒），请检查代理端口或服务可达性";if(web.Status==WebExceptionStatus.NameResolutionFailure||web.Status==WebExceptionStatus.ProxyNameResolutionFailure)return "域名解析失败，请检查 DNS 或代理";if(web.Status==WebExceptionStatus.ConnectFailure)return "无法连接，请检查 VPN / 系统代理是否仍在运行";if(web.Status==WebExceptionStatus.TrustFailure||web.Status==WebExceptionStatus.SecureChannelFailure)return "HTTPS 证书或 TLS 连接失败";return "HTTPS 请求失败（"+web.Status+"）";}return e is ArgumentException?e.Message:"属地服务返回无效数据，请稍后重试";}
 public static NetworkExit Fetch(){return Fetch("system","");}
 public static NetworkExit Fetch(string mode,string address){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var req=(HttpWebRequest)WebRequest.Create("https://ipwho.is/");req.Proxy=Proxy(mode,address);req.KeepAlive=false;req.Timeout=8000;req.ReadWriteTimeout=8000;req.UserAgent="ConanDesktopAssistant/5.19";using(var response=req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){char[] buffer=new char[32769];int total=0,n;while(total<buffer.Length&&(n=reader.Read(buffer,total,buffer.Length-total))>0)total+=n;if(total>32768)throw new InvalidDataException("属地响应过大");return Parse(new string(buffer,0,total));}}
}
